// Plans a three-day trip, independently checks its estimated costs, and allows one revision.
// Exact dates are used when supplied; otherwise the plan must flag seasonal assumptions.

budget { tokens: 12000 calls: 8 }

agent Planner {
    model: "gpt-6-luna"
    prompt: "trip_planner"
    temperature: 0.4
    guard { pii: mask }
    output_schema: { itinerary: string }
}

agent BudgetChecker {
    model: "gpt-6-luna"
    prompt: "budget_checker"
    temperature: 0.1
    tools: [calculator]
    max_iterations: 3
    guard { pii: mask }
    output_schema: {
        status: enum["FIT", "OVER", "UNVERIFIABLE"],
        total_estimate: number,
        discrepancy: number,
        assumptions: string
    }
}

workflow Main(trip_city_value, trip_budget_amount, trip_interest_list, trip_travel_dates, trip_expense_scope) {
    alt (trip_city_value == "") {
        human_prompt "Please provide the missing city, budget, and interests. Include exact travel dates if available; otherwise say dates are unavailable. Include a currency and any expense scope you want to use." -> traveler_clarification_text
        return "Please rerun with the required trip details. Your clarification was: {traveler_clarification_text}"
    } else {
        alt (trip_budget_amount == "") {
            human_prompt "Please provide the missing city, budget, and interests. Include exact travel dates if available; otherwise say dates are unavailable. Include a currency and any expense scope you want to use." -> traveler_clarification_text
            return "Please rerun with the required trip details. Your clarification was: {traveler_clarification_text}"
        } else {
            alt (trip_interest_list == "") {
                human_prompt "Please provide the missing city, budget, and interests. Include exact travel dates if available; otherwise say dates are unavailable. Include a currency and any expense scope you want to use." -> traveler_clarification_text
                return "Please rerun with the required trip details. Your clarification was: {traveler_clarification_text}"
            }
        }
    }

    delegate "Create a practical three-day itinerary for this city: {trip_city_value}\nBudget and currency as provided: {trip_budget_amount}\nInterests: {trip_interest_list}\nExact travel dates, if provided: {trip_travel_dates}\nExpense scope, if provided: {trip_expense_scope}" to Planner -> itinerary_record expecting { itinerary: string } retry 1 backoff 2s timeout 45s on_failure {
        human_prompt "The itinerary could not be created. Please retry the workflow or provide corrected trip details." -> planner_retry_reply
        return "The itinerary could not be created. Please retry. Your response: {planner_retry_reply}"
    }

    delegate "Independently check this three-day itinerary against the stated budget. Use the calculator for arithmetic. Budget and currency: {trip_budget_amount}\nExpense scope: {trip_expense_scope}\nItinerary:\n{itinerary_record.itinerary}\nCount round-trip transport, lodging, local transit, meals, and activities unless the user specified a different scope. Return FIT only when the included costs and assumptions can be checked and the total is within budget. Return OVER when the checkable total exceeds budget. Return UNVERIFIABLE when the costs, currency, or assumptions are too uncertain or incomplete to establish a fit. State the estimated total, the amount over budget as a positive discrepancy (or zero when not over), and the assumptions." to BudgetChecker -> initial_check expecting {
        status: enum["FIT", "OVER", "UNVERIFIABLE"],
        total_estimate: number,
        discrepancy: number,
        assumptions: string
    } retry 1 backoff 2s timeout 45s on_failure {
        human_prompt "The independent budget check could not be completed. Please retry the workflow or provide corrected budget information." -> checker_retry_reply
        return "The budget check could not be completed. This itinerary is not verified as within budget. Please retry. Your response: {checker_retry_reply}"
    }

    alt (initial_check.status == "FIT") {
        return "Budget verified within the stated budget. Estimated total: {initial_check.total_estimate}. Assumptions: {initial_check.assumptions}\n\n{itinerary_record.itinerary}"
    }

    loop until (revised_check.status == "FIT") max 1 {
        delegate "Revise this itinerary once to address the independent check. Keep the city, three-day duration, interests, dates, and stated expense scope. If dates are absent, keep the plan date-agnostic and flag seasonal assumptions. Reduce costs or clarify estimates where possible; do not claim that uncertain costs are verified.\nBudget and currency: {trip_budget_amount}\nCheck status: {initial_check.status}\nEstimated total: {initial_check.total_estimate}\nDiscrepancy: {initial_check.discrepancy}\nChecker assumptions: {initial_check.assumptions}\nPrevious itinerary:\n{itinerary_record.itinerary}" to Planner -> revised_itinerary_record expecting { itinerary: string } retry 1 backoff 2s timeout 45s on_failure {
            human_prompt "The itinerary revision could not be completed. Please retry the workflow." -> planner_retry_reply
            return "The itinerary revision could not be completed. Please retry. Your response: {planner_retry_reply}"
        }

        delegate "Independently check this revised three-day itinerary against the stated budget. Use the calculator for arithmetic. Budget and currency: {trip_budget_amount}\nExpense scope: {trip_expense_scope}\nItinerary:\n{revised_itinerary_record.itinerary}\nCount round-trip transport, lodging, local transit, meals, and activities unless the user specified a different scope. Return FIT only when the included costs and assumptions can be checked and the total is within budget. Return OVER when the checkable total exceeds budget. Return UNVERIFIABLE when the costs, currency, or assumptions are too uncertain or incomplete to establish a fit. State the estimated total, the amount over budget as a positive discrepancy (or zero when not over), and the assumptions." to BudgetChecker -> revised_check expecting {
            status: enum["FIT", "OVER", "UNVERIFIABLE"],
            total_estimate: number,
            discrepancy: number,
            assumptions: string
        } retry 1 backoff 2s timeout 45s on_failure {
            human_prompt "The independent budget check could not be completed. Please retry the workflow or provide corrected budget information." -> checker_retry_reply
            return "The budget check could not be completed. This itinerary is not verified as within budget. Please retry. Your response: {checker_retry_reply}"
        }
    } on_exhausted {
        human_prompt "After one revision, the itinerary is still over budget or its costs remain unverifiable. Remaining status: {revised_check.status}. Estimated total: {revised_check.total_estimate}. Amount over budget: {revised_check.discrepancy}. Remaining assumptions or uncertainty: {revised_check.assumptions}\n\nItinerary:\n{revised_itinerary_record.itinerary}\nHow would you like to proceed?" -> traveler_next_step
        return "After one revision, the plan is not verified within budget. Status: {revised_check.status}. Estimated total: {revised_check.total_estimate}. Discrepancy: {revised_check.discrepancy}. Assumptions: {revised_check.assumptions}\nYour response: {traveler_next_step}\n\n{revised_itinerary_record.itinerary}"
    }

    return "Budget verified within the stated budget after one revision. Estimated total: {revised_check.total_estimate}. Assumptions: {revised_check.assumptions}\n\n{revised_itinerary_record.itinerary}"
}
